mapper.select:
SELECT

FROM cms_page p
LEFT JOIN cms_page parent ON parent.site_id = p.site_id AND parent.id = p.parent_id

    p.site_id = #{siteId}

        AND p.status = #{status}


        AND
        (
            p.title ILIKE CONCAT('%', #{query}, '%')
            OR p.slug ILIKE CONCAT('%', #{query}, '%')
            OR COALESCE(p.summary, '') ILIKE CONCAT('%', #{query}, '%')
            OR COALESCE(p.content, '') ILIKE CONCAT('%', #{query}, '%')
            OR COALESCE(p.author, '') ILIKE CONCAT('%', #{query}, '%')
        )


ORDER BY COALESCE(p.sort_order, 0) ASC, p.updated_at DESC, p.id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*) FROM cms_page p
p.site_id = #{siteId}
AND p.status = #{status}
AND ( p.title ILIKE CONCAT('%', #{query}, '%') OR p.slug ILIKE CONCAT('%', #{query}, '%') OR COALESCE(p.summary, '') ILIKE CONCAT('%', #{query}, '%') OR COALESCE(p.content, '') ILIKE CONCAT('%', #{query}, '%') OR COALESCE(p.author, '') ILIKE CONCAT('%', #{query}, '%') )

SELECT

FROM cms_page p
LEFT JOIN cms_page parent ON parent.site_id = p.site_id AND parent.id = p.parent_id
WHERE p.site_id = #{siteId}
  AND p.id = #{id}

